/**
 * jev-vercel-sandbox — Claude Mod (EARLY ACCESS)
 *
 * Every Bash command Claude is about to run is judged by TypeSafe's Jev: a
 * command dangerous enough (destructive, remote code, a change to the machine,
 * data leaving it) never runs on the person's machine. It runs in a Vercel
 * Sandbox, an isolated Linux microVM started when the session starts, and its
 * output comes back as the Bash tool's result, with a note telling Claude
 * where it ran.
 *
 *   session.start  registers /jev-vercel-sandbox, opens the side pane, starts the sandbox
 *   turn.start     records the user's request (the judge's intent)
 *   tool.call      Bash only: plain reads stay local; the rest go to the judge,
 *                  and a dangerous one runs in the sandbox instead of `next`
 *   session.end    stops the sandbox
 *   ui.render      the pane: sandbox state, the judge, the last commands it ran
 *
 * Vercel credentials and Jev keys come from the plugin's options
 * (pluginConfigs["jev-vercel-sandbox@skills-dir"].options in user settings), with
 * VERCEL_TOKEN / VERCEL_OIDC_TOKEN / VERCEL_TEAM_ID / VERCEL_PROJECT_ID as a
 * fallback. Never from this code. Needs CLAUDE_CODE_ENABLE_FUNCTION_HOOKS=1
 * (Claude Code >= 2.1.259).
 *
 * Privacy: with a Jev key set, the user's latest request and each judged
 * command go to that backend. A sandboxed command goes to Vercel; no local
 * file or environment variable does.
 */
import type { Register } from 'claude-code'
import {
  BUILTIN_LABELS,
  DEFAULT_BASE_URL,
  DEFAULT_MODEL,
  classifyText,
  decide,
  describeJudgement,
  endpoint,
  isPlainRead,
  readJudgement,
  requestBody,
  requestHeaders,
  selectProvider,
  shortCommand,
  stateText,
  verdictReason,
} from './judge.ts'
import type { Judgement, Provider, Verdict } from './judge.ts'
import { DEFAULT_API_URL, client, resolveCredentials } from './vercel.ts'
import type { Client, CreateOptions, Credentials, Fetch, RunResult, SandboxInfo } from './vercel.ts'

const PANE = 'jev-vercel-sandbox'
const COMMAND = 'jev-vercel-sandbox'
const TAG = '[jev-vercel-sandbox]'
const RECENT = 8
// what the Bash tool itself keeps inline
const MAX_OUTPUT = 30_000
// session.start waits this long for the sandbox; past it the session goes on and the start finishes in the background
const START_WAIT_MS = 8_000
const POLL_MS = 500
const POLL_TRIES = 12

type State = 'off' | 'starting' | 'ready' | 'failed' | 'stopped'
type Ran = { command: string; exitCode: number | null; ms: number; reason: string; error?: string }

let state: State = 'off'
let info: SandboxInfo | undefined
let lastError: string | undefined
let starting: Promise<void> | undefined
let intent = ''
let now = 0
let isOpen = false
const recent: Ran[] = []
const judgements = new Map<string, Verdict>()
const tally = { local: 0, sandbox: 0, denied: 0 }

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`

function cap(text: string): string {
  return text.length > MAX_OUTPUT ? `${text.slice(0, MAX_OUTPUT)}\n… (${text.length - MAX_OUTPUT} more characters cut by jev-vercel-sandbox)` : text
}

function minutesLeft(): number | null {
  if (!info || !info.timeout || !info.startedAt || !now) return null
  return Math.max(0, Math.round((info.startedAt + info.timeout - now) / 60_000))
}

function statusLine(): string {
  const where = state === 'ready' ? 'ready' : state === 'starting' ? 'starting…' : state === 'off' ? 'not configured' : state
  return `sandbox · ${where} · ${tally.sandbox} sandboxed · ${tally.local} local${tally.denied ? ` · ${tally.denied} refused` : ''}`
}

function remember(r: Ran): void {
  recent.push(r)
  if (recent.length > RECENT) recent.splice(0, recent.length - RECENT)
}

export const register: Register = (on, options) => {
  const text = (key: string, fallback = '') =>
    typeof options[key] === 'string' && options[key] ? (options[key] as string).trim() : fallback
  const number = (key: string, fallback: number) =>
    typeof options[key] === 'number' && Number.isFinite(options[key]) ? (options[key] as number) : fallback
  const flag = (key: string, fallback: boolean) => (typeof options[key] === 'boolean' ? (options[key] as boolean) : fallback)

  // the judge
  const typesafeKey = text('typesafeApiKey')
  const gatewayKey = text('gatewayApiKey')
  const active: Provider | null = selectProvider(text('provider', 'auto'), typesafeKey, gatewayKey)
  const apiKey = active === 'typesafe' ? typesafeKey : active === 'gateway' ? gatewayKey : ''
  const modelId = !active ? '' : active === 'typesafe' ? text('typesafeModel', DEFAULT_MODEL.typesafe) : text('gatewayModel', DEFAULT_MODEL.gateway)
  const judgeUrl = !active
    ? ''
    : active === 'typesafe'
      ? endpoint('typesafe', text('typesafeBaseUrl', DEFAULT_BASE_URL.typesafe))
      : endpoint('gateway', text('gatewayBaseUrl', DEFAULT_BASE_URL.gateway))
  const backend = active ? `${active} ${modelId}` : 'built-in classifier'
  const threshold = number('threshold', 0.5)
  const severityLine = number('severityThreshold', 2)
  const judgeTimeoutMs = number('judgeTimeoutMs', 2_000)
  const onJudgeError = text('onJudgeError', 'sandbox') === 'local' ? 'local' : 'sandbox'
  const whenUnavailable = text('whenUnavailable', 'deny') === 'local' ? 'local' : 'deny'
  const audit = text('mode', 'enforce') === 'audit'
  const logDecisions = flag('logDecisions', true)

  // the sandbox
  const apiBase = text('vercelApiUrl', DEFAULT_API_URL)
  const createOptions: CreateOptions = {
    timeoutMs: Math.max(1, number('sandboxTimeoutMinutes', 45)) * 60_000,
    image: text('sandboxImage') || undefined,
    vcpus: number('sandboxVcpus', 0) || undefined,
    persistent: flag('persistent', false),
  }
  const commandTimeoutMs = Math.min(600_000, Math.max(1_000, number('commandTimeoutMs', 120_000)))
  const startOnSessionStart = flag('startOnSessionStart', true)
  const openPanel = flag('openPanel', true)
  const columns = Math.min(80, Math.max(28, number('columns', 44)))

  let credentials: Credentials | undefined
  let credentialsKind = ''
  let missing: string[] = []

  /** Starts (or restarts) the sandbox and waits until its session runs. */
  async function start(api: Client, sleep: (ms: number) => Promise<void>): Promise<void> {
    state = 'starting'
    lastError = undefined
    try {
      let s = await api.create(createOptions)
      // kept at once, so a sandbox whose polling fails can still be found and stopped
      info = s
      for (let i = 0; s.status === 'pending' && i < POLL_TRIES; i++) {
        await sleep(POLL_MS)
        s = await api.get(s)
        info = s
      }
      if (s.status === 'running') state = 'ready'
      else {
        state = 'failed'
        lastError = `the sandbox is ${s.status}`
      }
    } catch (err) {
      state = 'failed'
      lastError = err instanceof Error ? err.message : String(err)
    }
  }

  /** The running sandbox, started or restarted as needed; throws when it cannot be had. */
  async function ready(api: Client, sleep: (ms: number) => Promise<void>): Promise<SandboxInfo> {
    if (starting) await starting.catch(() => undefined)
    // a start that outlived session.start's wait may have stopped polling while still pending: look again
    if (info && (state === 'starting' || state === 'failed')) {
      const fresh = await api.get(info).catch(() => undefined)
      if (fresh) {
        info = fresh
        if (fresh.status === 'running') {
          state = 'ready'
          lastError = undefined
        }
      }
    }
    const expired = info && info.timeout && now && info.startedAt + info.timeout <= now
    if (!info || state !== 'ready' || expired) {
      // never leave a replaced sandbox running (and billed) behind
      if (info && (info.status === 'running' || info.status === 'pending')) await api.stop(info).catch(() => undefined)
      starting = start(api, sleep)
      await starting
    }
    if (state !== 'ready' || !info) throw new Error(lastError ?? 'the sandbox is not running')
    return info
  }

  async function runThere(api: Client, sleep: (ms: number) => Promise<void>, command: string, timeoutMs: number): Promise<RunResult> {
    const s = await ready(api, sleep)
    try {
      return await api.run(s, command, timeoutMs)
    } catch (err) {
      // the session may have timed out or been stopped from the dashboard: look, restart once, retry
      const fresh = await api.get(s).catch(() => undefined)
      if (fresh?.status === 'running') throw err
      state = 'stopped'
      return api.run(await ready(api, sleep), command, timeoutMs)
    }
  }

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    await $.command
      .register({
        name: COMMAND,
        description: 'The Vercel Sandbox that runs dangerous commands (status|open|restart|stop|log)',
        argumentHint: '[status|open|restart|stop|log]',
        immediate: true,
      })
      .catch(err => $.ui.log(`${TAG} /${COMMAND} not registered: ${err}`))

    // a fresh load of the plugin starts from nothing
    info = undefined
    lastError = undefined
    starting = undefined
    recent.length = 0
    judgements.clear()
    tally.local = tally.sandbox = tally.denied = 0

    // env fallbacks, each read by its literal name (the engine lists what a module reads)
    const orEmpty = (v: string | undefined) => v ?? ''
    const token =
      text('vercelToken') ||
      orEmpty(await $.env.get('VERCEL_TOKEN').catch(() => undefined)) ||
      orEmpty(await $.env.get('VERCEL_OIDC_TOKEN').catch(() => undefined))
    const teamId = text('vercelTeamId') || orEmpty(await $.env.get('VERCEL_TEAM_ID').catch(() => undefined))
    const projectId = text('vercelProjectId') || orEmpty(await $.env.get('VERCEL_PROJECT_ID').catch(() => undefined))
    const resolved = resolveCredentials(token, teamId, projectId)
    now = await $.clock.now()
    if (resolved.ok) {
      credentials = resolved.credentials
      credentialsKind = resolved.kind
      state = 'stopped'
    } else {
      missing = resolved.missing
      state = 'off'
    }

    if (openPanel) {
      isOpen = true
      // unasked, the engine keeps it undrawn below 144 columns until the person opens it
      await $.ui.open({ id: PANE, title: 'sandbox', columns }).catch(err => {
        isOpen = false
        $.ui.log(`${TAG} pane not opened: ${err}`, { to: 'debug' })
      })
    }

    if (credentials && startOnSessionStart) {
      const api = client((url, init) => $.http.fetch(url, init), credentials, apiBase)
      starting = start(api, ms => $.clock.sleep(ms))
      await Promise.race([starting, $.clock.sleep(START_WAIT_MS)]).catch(() => undefined)
    }
    now = await $.clock.now()
    // start() moved it while this hook waited
    const after = state as State
    const got = info as SandboxInfo | undefined

    const where = got ? `${got.name} · ${got.region} · ${got.vcpus} vCPU` : after === 'starting' ? 'still starting' : lastError ?? 'starts on the first dangerous command'
    $.ui.log(
      credentials
        ? `${TAG} ${after === 'ready' ? 'sandbox ready' : `sandbox ${after}`}: ${where} · judge ${backend} · threshold ${threshold.toFixed(2)}${audit ? ' · audit' : ''}`
        : `${TAG} not configured: set ${missing.join(', ')} in pluginConfigs["${$.plugin.name}@skills-dir"] (or "${$.plugin.name}" with --plugin-dir); dangerous commands are ${whenUnavailable === 'deny' ? 'refused' : 'run locally'} until then`,
    )
    if (after === 'failed') $.ui.toast(`jev-vercel-sandbox: the sandbox did not start (${lastError})`)
    $.ui.status(statusLine())
    $.ui.invalidate('ui.render')
    return r
  })

  on('turn.start', async ($, e, next) => {
    if (e.text.trim()) intent = e.text
    now = await $.clock.now()
    if (isOpen) $.ui.invalidate('ui.render')
    return next(e)
  })

  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const command = typeof e.command === 'string' ? e.command : ''
    if (!command.trim()) return next(e)
    const short = shortCommand(command)

    // 1. which way it goes
    let verdict: Verdict | undefined = isPlainRead(command)
      ? { route: 'local', hazard: null, probability: null, bySeverity: false, by: 'read-only' }
      : judgements.get(`${intent}\u0000${command}`)
    if (!verdict) {
      const startedAt = await $.clock.now()
      const state_ = stateText(intent, command, await $.session.cwd().catch(() => ''))
      let judgement: Judgement | null = null
      try {
        if (active) {
          const response = await Promise.race([
            $.http.fetch(judgeUrl, { method: 'POST', headers: requestHeaders(active, apiKey, modelId), body: requestBody(active, state_, modelId) }),
            $.clock.sleep(judgeTimeoutMs),
          ])
          if (response && response.ok) judgement = readJudgement(response.text)
          else $.ui.log(`${TAG} judge: ${response ? `${active} responded ${response.status}` : `no answer in ${judgeTimeoutMs}ms`}`)
          if (judgement) verdict = decide(judgement, threshold, severityLine)
        } else {
          const label = await $.model.classify(classifyText(state_), BUILTIN_LABELS)
          if (label === 'local' || label === 'sandbox') verdict = { route: label, hazard: null, probability: null, bySeverity: false, by: 'built-in' }
        }
      } catch (err) {
        $.ui.log(`${TAG} judge failed: ${String(err)}`)
      }
      const ms = (await $.clock.now()) - startedAt
      if (logDecisions && active) $.ui.log(`${TAG} judge ${short}: ${describeJudgement(judgement, ms)}`)
      if (verdict) {
        judgements.set(`${intent}\u0000${command}`, verdict)
        if (judgements.size > 300) judgements.delete(judgements.keys().next().value as string)
      } else {
        verdict = { route: onJudgeError, hazard: null, probability: null, bySeverity: false, by: 'judge error' }
      }
    }
    const reason = verdictReason(verdict)

    if (verdict.route === 'local' || audit) {
      tally.local += 1
      if (logDecisions && verdict.by !== 'read-only') $.ui.log(`${TAG} ${audit && verdict.route === 'sandbox' ? 'audit: would sandbox' : 'local'} ${short} (${reason})`)
      $.ui.status(statusLine())
      return next(e)
    }

    // 2. dangerous: run it in the sandbox, never here
    if (!credentials) {
      if (whenUnavailable === 'local') {
        tally.local += 1
        $.ui.log(`${TAG} local ${short}: judged dangerous (${reason}) but no sandbox is configured`)
        return next(e)
      }
      tally.denied += 1
      $.ui.status(statusLine())
      return {
        deny: `jev-vercel-sandbox judged this command dangerous (${reason}) and would run it in a Vercel Sandbox, but none is configured (missing ${missing.join(', ')}). It was not run. Tell the user; do not retry it another way.`,
      }
    }

    const api = client((url, init) => $.http.fetch(url, init), credentials, apiBase)
    const sleep = (ms: number) => $.clock.sleep(ms)
    const timeoutMs = Math.min(600_000, typeof e.timeout === 'number' && e.timeout > 0 ? e.timeout : commandTimeoutMs)
    $.ui.status(`sandbox · running ${short}`)
    if (logDecisions) $.ui.log(`${TAG} sandbox ${short} (${reason})`)
    const startedAt = await $.clock.now()
    let result: RunResult
    try {
      result = await runThere(api, sleep, command, timeoutMs)
    } catch (err) {
      const why = err instanceof Error ? err.message : String(err)
      lastError = why
      now = await $.clock.now()
      remember({ command: short, exitCode: null, ms: now - startedAt, reason, error: why })
      $.ui.invalidate('ui.render')
      if (whenUnavailable === 'local') {
        tally.local += 1
        $.ui.log(`${TAG} sandbox unavailable (${why}); ran ${short} locally`)
        $.ui.status(statusLine())
        return next(e)
      }
      tally.denied += 1
      $.ui.log(`${TAG} sandbox unavailable (${why}); refused ${short}`)
      $.ui.status(statusLine())
      return {
        deny: `jev-vercel-sandbox judged this command dangerous (${reason}) and the Vercel Sandbox could not run it (${why}). It was not run on the user's machine either. Tell the user; do not retry it another way.`,
      }
    }
    now = await $.clock.now()
    const ms = Math.round(result.durationMs ?? now - startedAt)
    tally.sandbox += 1
    remember({ command: short, exitCode: result.exitCode, ms, reason, error: result.error })
    $.ui.status(statusLine())
    $.ui.invalidate('ui.render')

    const s = info!
    const exit = result.exitCode === null ? 'no exit code' : `exit ${result.exitCode}`
    const header = `[ran in Vercel Sandbox ${s.name}, not on this machine · ${reason} · ${exit} · ${ms}ms]`
    const stderr = [result.stderr, result.error ? `jev-vercel-sandbox: ${result.error}` : '', result.exitCode ? `Exit code ${result.exitCode}` : '']
      .filter(Boolean)
      .join('\n')
    return {
      result: { stdout: cap(`${header}\n${result.stdout}`), stderr: cap(stderr), interrupted: false },
      context: [
        `This Bash command did not run on the user's machine. jev-vercel-sandbox judged it dangerous (${reason}) and ran it in an isolated Vercel Sandbox (a Linux microVM, working directory ${s.cwd || 'its default'}), ` +
          `which has none of the project's files, the user's environment variables or credentials. Nothing on the user's machine changed. ${exit}. ` +
          (e.run_in_background ? 'It ran in the foreground there, not in the background. ' : '') +
          'Files it wrote exist only in the sandbox, which is stopped when the session ends. If the task needs this to happen on the user\'s machine, tell the user and let them run it themselves.',
      ],
    }
  })

  on('session.end', async ($, e, next) => {
    if (credentials && info && state === 'ready' && flag('stopOnExit', true)) {
      const api = client((url, init) => $.http.fetch(url, init), credentials, apiBase)
      const budget = Math.max(0, Math.min(2_000, next.budget.remainingMs - 500))
      await Promise.race([api.stop(info).catch(() => undefined), $.clock.sleep(budget)]).catch(() => undefined)
      state = 'stopped'
    }
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    now = await $.clock.now()
    const api = credentials ? client((url, init) => $.http.fetch(url, init), credentials, apiBase) : undefined
    if (arg === 'log') {
      if (!recent.length) return { text: 'jev-vercel-sandbox: nothing has run in the sandbox yet' }
      return { text: recent.map(r => `${r.error && r.exitCode === null ? '✗' : r.exitCode === 0 ? '✓' : '!'} ${r.command}  · ${r.exitCode ?? r.error} · ${r.reason}`).join('\n') }
    }
    if (arg === 'restart' || arg === 'start') {
      if (!api) return { text: `jev-vercel-sandbox: not configured (missing ${missing.join(', ')})` }
      if (info && state === 'ready') await api.stop(info).catch(() => undefined)
      starting = start(api, ms => $.clock.sleep(ms))
      await starting
      now = await $.clock.now()
      $.ui.status(statusLine())
      $.ui.invalidate('ui.render')
      return { text: state === 'ready' ? `jev-vercel-sandbox: ${info!.name} ready` : `jev-vercel-sandbox: did not start (${lastError})` }
    }
    if (arg === 'stop') {
      if (api && info && state === 'ready') await api.stop(info).catch(err => $.ui.log(`${TAG} stop failed: ${err}`))
      state = credentials ? 'stopped' : 'off'
      $.ui.status(statusLine())
      $.ui.invalidate('ui.render')
      return { text: 'jev-vercel-sandbox: stopped; the next dangerous command starts a new one' }
    }
    if (arg === 'open' || arg === '') {
      isOpen = true
      await $.ui.open({ id: PANE, title: 'sandbox', focus: true, columns }).catch(() => (isOpen = false))
      $.ui.invalidate('ui.render')
    }
    const left = minutesLeft()
    return {
      text: [
        `jev-vercel-sandbox: ${statusLine()}`,
        credentials
          ? `sandbox: ${info ? `${info.name} · ${info.status} · ${info.region} · ${info.vcpus} vCPU · ${info.memory} MB${left !== null ? ` · stops in ${left}m` : ''}` : 'not started'} (${credentialsKind})`
          : `not configured: missing ${missing.join(', ')}`,
        `judge: ${backend} · threshold ${threshold.toFixed(2)} · severity ${severityLine.toFixed(1)}${audit ? ' · audit (nothing is sandboxed)' : ''}`,
        lastError ? `last error: ${lastError}` : '',
        `/${COMMAND} open · restart · stop · log`,
      ]
        .filter(Boolean)
        .join('\n'),
    }
  })

  on('ui.close', async ($, e, next) => {
    if (e.id === PANE) isOpen = false
    return next(e)
  })

  on('ui.press', async ($, e, next) => {
    if (e.plugin !== $.plugin.name || e.requestId !== PANE) return next(e)
    const r = await next(e)
    if (e.element === 'close') {
      await $.ui.close({ id: PANE }).catch(() => undefined)
      isOpen = false
      return r
    }
    if (!credentials) return r
    const api = client((url, init) => $.http.fetch(url, init), credentials, apiBase)
    if (e.element === 'restart') {
      if (info && state === 'ready') await api.stop(info).catch(() => undefined)
      starting = start(api, ms => $.clock.sleep(ms))
      $.ui.invalidate('ui.render')
      await starting
      if (state === 'failed') $.ui.toast(`jev-vercel-sandbox: the sandbox did not start (${lastError})`)
    } else if (e.element === 'stop' && info && state === 'ready') {
      await api.stop(info).catch(err => $.ui.toast(`jev-vercel-sandbox: stop failed: ${err}`))
      state = 'stopped'
    }
    now = await $.clock.now()
    $.ui.status(statusLine())
    $.ui.invalidate('ui.render')
    return r
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE) return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)
    const width = Math.max(20, e.props.bodyColumns - 1)
    const fit = (s: string, w = width) => (s.length > w ? `${s.slice(0, Math.max(1, w - 1))}…` : s)
    const noop = () => {}
    const left = minutesLeft()

    const badge =
      state === 'ready' ? (
        <Text color="green" bold>● ready</Text>
      ) : state === 'starting' ? (
        <Text color="yellow" bold>◌ starting…</Text>
      ) : state === 'failed' ? (
        <Text color="red" bold>✗ failed</Text>
      ) : state === 'stopped' ? (
        <Text color="yellow" bold>○ stopped</Text>
      ) : (
        <Text color="red" bold>– not configured</Text>
      )

    const explain =
      state === 'ready'
        ? 'Ready. Commands Jev judges dangerous run here, in an isolated Linux microVM, instead of on your machine.'
        : state === 'starting'
          ? 'Starting the microVM. Dangerous commands wait for it.'
          : state === 'stopped'
            ? 'Not running. The next dangerous command starts a new one; restart starts it now.'
            : state === 'failed'
              ? `It did not start: ${lastError ?? 'unknown error'}. Dangerous commands are ${whenUnavailable === 'deny' ? 'refused' : 'run locally'} until it does.`
              : `Set ${missing.join(', ')} in the plugin's options (settings.json, pluginConfigs["${$.plugin.name}@skills-dir"].options). Until then dangerous commands are ${whenUnavailable === 'deny' ? 'refused' : 'run locally'}.`

    return (
      <Box flexDirection="column">
        <Text bold>{fit('Vercel Sandbox')}</Text>
        {badge}
        {info ? (
          <Box key="info" flexDirection="column" marginTop={1}>
            <Text>{fit(info.name)}</Text>
            <Text dimColor>{fit(`${info.region} · ${info.vcpus} vCPU · ${info.memory} MB`)}</Text>
            {info.image ? <Text dimColor>{fit(info.image)}</Text> : null}
            {left !== null && state === 'ready' ? <Text dimColor>{fit(`stops in ${left}m`)}</Text> : null}
          </Box>
        ) : null}
        <Box key="explain" marginTop={1}>
          <Text wrap="wrap">{explain}</Text>
        </Box>

        <Box key="judge-head" marginTop={1}>
          <Text bold color="cyan">Judge</Text>
        </Box>
        <Text dimColor>{fit(`${backend}${audit ? ' · audit' : ''}`)}</Text>
        <Text dimColor>{fit(`sandbox at ${threshold.toFixed(2)} · severity ${severityLine.toFixed(1)}`)}</Text>
        <Text dimColor>{fit(`${plural(tally.sandbox, 'sandboxed')} · ${tally.local} local${tally.denied ? ` · ${tally.denied} refused` : ''}`)}</Text>

        <Box key="recent-head" marginTop={1}>
          <Text bold color="cyan">{`Ran in the sandbox (${recent.length})`}</Text>
        </Box>
        {recent.length === 0 ? <Text dimColor>nothing yet</Text> : null}
        {recent
          .slice()
          .reverse()
          .map((r, i) => {
            const ok = r.exitCode === 0
            const mark = r.exitCode === null ? '✗ ' : ok ? '✓ ' : '! '
            const tail = r.exitCode === null ? ' failed' : ` ${r.exitCode}`
            return (
              <Box key={`run:${i}`} flexDirection="row">
                <Text color={r.exitCode === null ? 'red' : ok ? 'green' : 'yellow'}>{mark}</Text>
                <Text>{fit(r.command, width - 2 - tail.length)}</Text>
                <Text dimColor>{tail}</Text>
              </Box>
            )
          })}

        <Box key="toolbar" marginTop={1} flexDirection="row" columnGap={1}>
          {credentials ? <Button key="restart" label={state === 'ready' ? 'restart' : 'start'} hotkey="r" onPress={noop} /> : null}
          {credentials && state === 'ready' ? <Button key="stop" label="stop" onPress={noop} /> : null}
          <Button key="close" label="close" onPress={noop} />
        </Box>
      </Box>
    )
  })
}

files.hooks/judge.ts:
/**
 * jev-vercel-sandbox — the judge: TypeSafe's Jev asked whether one Bash command is
 * dangerous enough to leave the machine for a Vercel Sandbox.
 *
 * No `$` and no I/O here. The wire shapes are jev-auto-mode's (TypeSafe's
 * System One API and the Vercel AI Gateway's evaluation-model endpoint, both
 * with `ai-gateway-protocol-version`); the battery is this mod's own.
 */

export type Provider = 'typesafe' | 'gateway'

export const DEFAULT_BASE_URL: Record<Provider, string> = {
  typesafe: 'https://api.typesafe.ai',
  gateway: 'https://ai-gateway.vercel.sh/v4/ai',
}

export const DEFAULT_MODEL: Record<Provider, string> = {
  typesafe: 'jev-latest',
  gateway: 'typesafe-ai/jev',
}

/** `@ai-sdk/gateway`'s AI_GATEWAY_PROTOCOL_VERSION. */
const AI_GATEWAY_PROTOCOL_VERSION = '0.0.1'

export function selectProvider(forced: string, typesafeKey: string, gatewayKey: string): Provider | null {
  if (forced === 'builtin') return null
  if (forced === 'typesafe') return typesafeKey ? 'typesafe' : null
  if (forced === 'gateway') return gatewayKey ? 'gateway' : null
  if (typesafeKey) return 'typesafe'
  if (gatewayKey) return 'gateway'
  return null
}

export function endpoint(provider: Provider, baseUrl: string): string {
  const root = baseUrl.replace(/\/+$/, '')
  return provider === 'typesafe' ? `${root}/v1/systemone` : `${root}/evaluation-model`
}

export type Hazard = 'destructive' | 'remote_code' | 'system_change' | 'exfiltration'

type Question = { instructions: string; yes: string; no: string }

/** What could go wrong on the person's machine if this command ran there. */
export const BATTERY: Record<Hazard, Question> = {
  destructive: {
    instructions:
      'Would this shell command delete, overwrite or irreversibly change files, git history, databases or infrastructure (for example rm -rf, git reset --hard, a force push, DROP TABLE, dd, mkfs, terraform destroy)?',
    yes: 'It destroys or irreversibly changes something that may not be recoverable.',
    no: 'It reads, or makes an ordinary, recoverable change.',
  },
  remote_code: {
    instructions:
      'Does this shell command download and run code from the internet, or install or execute a package, script or binary whose origin is not already part of the project (for example curl | sh, npx of an unknown package, pip install from a URL)?',
    yes: 'It runs code that has not been reviewed.',
    no: 'It runs only code already on the machine or in the project.',
  },
  system_change: {
    instructions:
      'Does this shell command change the machine beyond the project: sudo, system packages, services, users, permissions, shell profiles, global config or environment?',
    yes: 'It changes the machine itself, not just the project.',
    no: 'It stays inside the project.',
  },
  exfiltration: {
    instructions:
      'Would this shell command send files, secrets, credentials or environment variables from this machine to somewhere outside it?',
    yes: 'It sends local data off the machine.',
    no: 'It sends nothing local off the machine.',
  },
}

export const HAZARDS = Object.keys(BATTERY) as Hazard[]

const SEVERITY_INSTRUCTIONS = 'If this command turned out to be a mistake on the developer\'s own machine, how bad would the damage be?'
export const SEVERITY_CRITERIA: readonly string[] = [
  'None: read-only or trivially undone.',
  'Mild: a local change that is easy to undo.',
  'Serious: lost work, a broken environment, or data leaving the machine.',
  'Severe: irreversible loss, a compromised machine, or leaked credentials.',
]

const SAFE_PROGRAMS = new Set([
  'ls', 'pwd', 'cat', 'head', 'tail', 'wc', 'echo', 'printf', 'which', 'type', 'file', 'stat', 'du', 'df',
  'grep', 'egrep', 'rg', 'tree', 'date', 'whoami', 'uname', 'basename', 'dirname', 'realpath', 'sort', 'uniq', 'diff', 'true',
])
const SAFE_GIT = new Set(['status', 'log', 'diff', 'show', 'rev-parse', 'blame', 'ls-files', 'describe'])
// `git branch -D x` and `git remote remove origin` write: these two are reads only with listing flags
const LISTING_GIT = new Set(['branch', 'remote'])
const LISTING_FLAGS = new Set(['-a', '-r', '-v', '-vv', '--all', '--remotes', '--list', '--verbose', '--show-current'])

/**
 * A command that plainly only reads: one program from a short list, no shell
 * operators, redirects or substitutions. These stay local without a call to
 * the judge. Anything else, however harmless, goes to the judge.
 */
export function isPlainRead(command: string): boolean {
  const c = command.trim()
  if (!c || /[;&|<>`$(){}\n\\]/.test(c)) return false
  const words = c.split(/\s+/)
  const program = words[0]!
  if (program === 'git') {
    const sub = words[1] ?? ''
    if (LISTING_GIT.has(sub)) return words.slice(2).every(w => LISTING_FLAGS.has(w))
    return SAFE_GIT.has(sub) && !words.some(w => /^--(output|exec)/.test(w))
  }
  if (program === 'find') return !words.some(w => /^-(delete|exec|execdir|ok|okdir|fprint|fls)/.test(w))
  // sed is left to the judge: its `w` command writes files without -i
  return SAFE_PROGRAMS.has(program)
}

/** What the judge reads: the user's request, then the command, whole. */
export function stateText(intent: string, command: string, cwd: string): string {
  return [
    "The user's latest request to an AI coding agent:",
    intent.trim() ? intent.trim().slice(0, 2000) : '(none recorded)',
    '',
    `The agent is about to run this shell command on the developer's own machine${cwd ? `, in ${cwd}` : ''}:`,
    command,
  ].join('\n')
}

function yesNo(provider: Provider, q: Question): Record<string, unknown> {
  if (provider === 'typesafe') return { type: 'noul', instructions: q.instructions, criteria: { true: q.yes, false: q.no } }
  return { type: 'boolean', instructions: `${q.instructions} Yes: ${q.yes} No: ${q.no}` }
}

export function requestBody(provider: Provider, state: string, model: string): string {
  const questions: Record<string, unknown> = {}
  for (const hazard of HAZARDS) questions[hazard] = yesNo(provider, BATTERY[hazard])
  questions.severity = { type: 'score', instructions: SEVERITY_INSTRUCTIONS, criteria: SEVERITY_CRITERIA }
  return JSON.stringify(provider === 'typesafe' ? { model, state, questions } : { state, questions })
}

export function requestHeaders(provider: Provider, apiKey: string, model: string): Record<string, string> {
  const common = { 'content-type': 'application/json', authorization: `Bearer ${apiKey}` }
  if (provider === 'typesafe') return common
  return {
    ...common,
    'ai-gateway-auth-method': 'api-key',
    'ai-model-id': model,
    'ai-gateway-protocol-version': AI_GATEWAY_PROTOCOL_VERSION,
    'ai-evaluation-model-specification-version': '4',
  }
}

export type Judgement = { probabilities: Record<Hazard, number>; severity: number | null }

/** Reads either backend's answer; a battery with any hazard unanswered reads as none. */
export function readJudgement(text: string): Judgement | null {
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return null
  }
  if (parsed === null || typeof parsed !== 'object') return null
  const answers = (parsed as { answers?: Record<string, Record<string, unknown>> }).answers
  if (!answers || typeof answers !== 'object') return null
  const probabilities = {} as Record<Hazard, number>
  for (const hazard of HAZARDS) {
    const a = answers[hazard]
    const p = typeof a?.noul === 'number' ? a.noul : typeof a?.probability === 'number' ? a.probability : null
    if (p === null) return null
    probabilities[hazard] = p
  }
  const severity = answers.severity
  return { probabilities, severity: typeof severity?.score === 'number' ? severity.score : null }
}

export type Route = 'local' | 'sandbox'

export type Verdict = {
  route: Route
  /** The hazard that sent it to the sandbox, or the likeliest one when it stayed local. */
  hazard: Hazard | null
  probability: number | null
  /** True when the severity alone crossed its line. */
  bySeverity: boolean
  by: 'read-only' | 'jev' | 'built-in' | 'judge error'
}

/** Sandbox when any hazard reaches `threshold`, or the severity reaches `severityLine`. */
export function decide(j: Judgement, threshold: number, severityLine: number): Verdict {
  let top: Hazard | null = null
  for (const h of HAZARDS) if (top === null || j.probabilities[h] > j.probabilities[top]) top = h
  const p = top === null ? null : j.probabilities[top]
  if (p !== null && p >= threshold) return { route: 'sandbox', hazard: top, probability: p, bySeverity: false, by: 'jev' }
  if (j.severity !== null && j.severity >= severityLine) return { route: 'sandbox', hazard: top, probability: p, bySeverity: true, by: 'jev' }
  return { route: 'local', hazard: top, probability: p, bySeverity: false, by: 'jev' }
}

export const BUILTIN_LABELS: readonly Route[] = ['local', 'sandbox']

/** The rubric the engine's small classifier reads when no Jev key is set. */
export function classifyText(state: string): string {
  return [
    'You route shell commands for an AI coding agent. Answer "sandbox" when the command is dangerous to run on the developer\'s own machine, "local" otherwise.',
    'Dangerous means any of:',
    ...HAZARDS.map(h => `- ${h}: ${BATTERY[h].instructions}`),
    'Ordinary development work (building, testing, reading, editing project files, git commits) is "local".',
    '',
    state,
  ].join('\n')
}

export function describeJudgement(j: Judgement | null, ms: number): string {
  const took = ` · ${Math.round(ms)}ms`
  if (!j) return `no answer${took}`
  const parts = (Object.entries(j.probabilities) as [Hazard, number][])
    .sort((a, b) => b[1] - a[1])
    .map(([h, p]) => `${h} ${p.toFixed(2)}`)
  if (j.severity !== null) parts.push(`severity ${j.severity.toFixed(1)}`)
  return parts.join(' · ') + took
}

export function verdictReason(v: Verdict): string {
  if (v.by === 'read-only') return 'plain read'
  if (v.by === 'judge error') return 'the judge gave no answer'
  if (v.by === 'built-in') return `built-in classifier: ${v.route}`
  if (v.hazard === null) return v.route
  const p = v.probability === null ? '' : ` ${v.probability.toFixed(2)}`
  return `${v.hazard.replace(/_/g, ' ')}${p}${v.bySeverity ? ', by severity' : ''}`
}

/** One line for the transcript, the panel and the status: the command, cut to fit. */
export function shortCommand(command: string, max = 60): string {
  const one = command.replace(/\s+/g, ' ').trim()
  return one.length > max ? `${one.slice(0, max - 1)}…` : one
}

files.hooks/vercel.ts:
/**
 * jev-vercel-sandbox — the Vercel Sandbox REST client.
 *
 * A mod runs without node_modules, so `@vercel/sandbox` is not available: this
 * speaks its HTTP API directly, through a `fetch` the hooks module hands in
 * (`(url, init) => $.http.fetch(url, init)`), so nothing here touches `$`.
 *
 * The endpoints are Vercel's REST API reference (vercel.com/docs/rest-api/sandboxes),
 * called the way `@vercel/sandbox` 3.5.0 calls them (dist/api-client/api-client.js):
 *
 *   POST /v3/sandboxes?teamId=…                       create → { sandbox, session, routes }
 *   GET  /v2/sandboxes/sessions/{id}?teamId=…         → { session, routes }
 *   POST /v2/sandboxes/sessions/{id}/cmd?teamId=…     { command, args, cwd, env, sudo, wait: true, logs: true, timeout }
 *                                                     → application/x-ndjson: { command } · { stream, data }… · { command: { exitCode } }
 *   POST /v2/sandboxes/sessions/{id}/stop?teamId=…    → { session }
 *
 * Base URL https://api.vercel.com (the SDK uses the equivalent
 * https://vercel.com/api), `Authorization: Bearer <token>`. An error body is
 * `{ error: { message } }`. `persistent` defaults to true on the server, so it
 * is always sent.
 */
import type { HttpInit, HttpResponse } from 'claude-code'

export type Fetch = (url: string, init: HttpInit) => Promise<HttpResponse>

export const DEFAULT_API_URL = 'https://api.vercel.com'

export type Credentials = { token: string; teamId: string; projectId: string }

export type SessionStatus = 'pending' | 'running' | 'stopping' | 'stopped' | 'failed' | 'aborted' | 'snapshotting'

export type SandboxInfo = {
  /** The sandbox's name (the SDK's `sandbox.name`). */
  name: string
  /** The current session: commands and stop go to it. */
  sessionId: string
  status: SessionStatus
  region: string
  vcpus: number
  memory: number
  /** The session's timeout, in ms. */
  timeout: number
  cwd: string
  image?: string
  /** Epoch ms the session started (or was requested, while pending). */
  startedAt: number
}

export type CreateOptions = {
  timeoutMs: number
  image?: string
  vcpus?: number
  persistent: boolean
}

export type RunResult = {
  exitCode: number | null
  stdout: string
  stderr: string
  durationMs?: number
  /** A `{ stream: "error" }` line, or a stream that ended before the command did. */
  error?: string
}

/** base64url → text, without `atob` (the mod runtime's lib is es2023 only). */
function decodeBase64Url(s: string): string {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'
  let bits = 0
  let value = 0
  const bytes: number[] = []
  for (const ch of s.replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_')) {
    const i = alphabet.indexOf(ch)
    if (i < 0) throw new Error('not base64url')
    value = (value << 6) | i
    bits += 6
    if (bits >= 8) {
      bits -= 8
      bytes.push((value >> bits) & 0xff)
    }
  }
  // UTF-8 without TextDecoder (not in the es2023 lib either)
  return decodeURIComponent(bytes.map(b => `%${b.toString(16).padStart(2, '0')}`).join(''))
}

/**
 * The claims a Vercel OIDC token carries (`owner_id` is the team,
 * `project_id` the project), as the SDK's `decodeUnverifiedToken` reads them.
 * Null for an access token, which is not a JWT.
 */
export function oidcClaims(token: string): { teamId: string; projectId?: string } | null {
  const parts = token.split('.')
  if (parts.length !== 3) return null
  try {
    const payload = JSON.parse(decodeBase64Url(parts[1]!)) as { owner_id?: unknown; project_id?: unknown }
    if (typeof payload.owner_id !== 'string') return null
    return { teamId: payload.owner_id, projectId: typeof payload.project_id === 'string' ? payload.project_id : undefined }
  } catch {
    return null
  }
}

/**
 * Credentials from the options (or the env fallbacks): an access token needs
 * the team and project ids beside it; an OIDC token carries both itself.
 */
export function resolveCredentials(
  token: string,
  teamId: string,
  projectId: string,
): { ok: true; credentials: Credentials; kind: 'access token' | 'oidc token' } | { ok: false; missing: string[] } {
  const t = token.trim()
  const claims = t ? oidcClaims(t) : null
  const team = teamId.trim() || claims?.teamId || ''
  const project = projectId.trim() || claims?.projectId || ''
  const missing = [!t && 'vercelToken', !team && 'vercelTeamId', !project && 'vercelProjectId'].filter((m): m is string => !!m)
  if (missing.length) return { ok: false, missing }
  return { ok: true, credentials: { token: t, teamId: team, projectId: project }, kind: claims ? 'oidc token' : 'access token' }
}

export function apiUrl(base: string, path: string, teamId: string): string {
  return `${base.replace(/\/+$/, '')}${path}?teamId=${encodeURIComponent(teamId)}`
}

export function headers(c: Credentials): Record<string, string> {
  return { authorization: `Bearer ${c.token}`, 'content-type': 'application/json', 'user-agent': 'jev-vercel-sandbox (claude-code mod)' }
}

export function createBody(c: Credentials, o: CreateOptions): string {
  const body: Record<string, unknown> = {
    projectId: c.projectId,
    ports: [],
    timeout: o.timeoutMs,
    persistent: o.persistent,
  }
  if (o.image) body.image = o.image
  if (o.vcpus) body.resources = { vcpus: o.vcpus }
  return JSON.stringify(body)
}

/** The Bash tool's command, run by bash in the sandbox with no local env forwarded. */
export function commandBody(command: string, timeoutMs: number, cwd?: string): string {
  return JSON.stringify({
    command: 'bash',
    args: ['-c', command],
    cwd: cwd || undefined,
    env: {},
    sudo: false,
    wait: true,
    logs: true,
    timeout: timeoutMs,
  })
}

/** The server's `{ error: { message } }`, else the status and the start of the body. */
export function errorOf(r: HttpResponse): string {
  try {
    const m = (JSON.parse(r.text) as { error?: { message?: unknown } }).error?.message
    if (typeof m === 'string' && m) return `${r.status}: ${m}`
  } catch {}
  return `${r.status}${r.text ? `: ${r.text.slice(0, 200)}` : ''}`
}

function num(v: unknown, fallback = 0): number {
  return typeof v === 'number' && Number.isFinite(v) ? v : fallback
}

function readSessionObject(session: Record<string, unknown>, sandbox?: Record<string, unknown>): SandboxInfo | null {
  if (typeof session.id !== 'string' || typeof session.status !== 'string') return null
  return {
    name: typeof sandbox?.name === 'string' ? sandbox.name : session.id,
    sessionId: session.id,
    status: session.status as SessionStatus,
    region: typeof session.region === 'string' ? session.region : '',
    vcpus: num(session.vcpus),
    memory: num(session.memory),
    timeout: num(session.timeout),
    cwd: typeof session.cwd === 'string' ? session.cwd : '',
    image: typeof sandbox?.image === 'string' ? sandbox.image : undefined,
    startedAt: num(session.startedAt, num(session.requestedAt, num(session.createdAt))),
  }
}

/** `{ sandbox, session, routes }` (create) or `{ session, routes }` (get). */
export function readSandbox(text: string, previousName?: string): SandboxInfo | null {
  let parsed: unknown
  try {
    parsed = JSON.parse(text)
  } catch {
    return null
  }
  if (!parsed || typeof parsed !== 'object') return null
  const { session, sandbox } = parsed as { session?: unknown; sandbox?: unknown }
  if (!session || typeof session !== 'object') return null
  const info = readSessionObject(session as Record<string, unknown>, sandbox && typeof sandbox === 'object' ? (sandbox as Record<string, unknown>) : undefined)
  if (info && !sandbox && previousName) info.name = previousName
  return info
}

/**
 * The command endpoint's ndjson, read whole: the first line names the
 * command, log lines follow, and a line with `command.exitCode` ends it.
 */
export function readCommandStream(text: string): RunResult {
  const out: RunResult = { exitCode: null, stdout: '', stderr: '' }
  let finished = false
  for (const line of text.split('\n')) {
    if (!line.trim()) continue
    let chunk: Record<string, unknown>
    try {
      chunk = JSON.parse(line) as Record<string, unknown>
    } catch {
      continue
    }
    const command = chunk.command as { exitCode?: unknown; durationMs?: unknown } | undefined
    if (command && typeof command === 'object') {
      if (typeof command.exitCode === 'number') {
        out.exitCode = command.exitCode
        if (typeof command.durationMs === 'number') out.durationMs = command.durationMs
        finished = true
      }
      continue
    }
    if (chunk.stream === 'stdout' && typeof chunk.data === 'string') out.stdout += chunk.data
    else if (chunk.stream === 'stderr' && typeof chunk.data === 'string') out.stderr += chunk.data
    else if (chunk.stream === 'error') {
      const d = chunk.data as { code?: unknown; message?: unknown } | undefined
      out.error = `${typeof d?.code === 'string' ? d.code : 'error'}: ${typeof d?.message === 'string' ? d.message : 'the sandbox reported an error'}`
    }
  }
  if (!finished && !out.error) out.error = 'the stream ended before the command finished'
  return out
}

export type Client = {
  create(o: CreateOptions): Promise<SandboxInfo>
  get(s: SandboxInfo): Promise<SandboxInfo>
  run(s: SandboxInfo, command: string, timeoutMs: number): Promise<RunResult>
  stop(s: SandboxInfo): Promise<void>
}

/** The four calls this mod makes, over the fetch it is handed. Each throws with the API's message on a non-2xx. */
export function client(fetch: Fetch, c: Credentials, base = DEFAULT_API_URL): Client {
  const call = async (path: string, init: HttpInit) => {
    const r = await fetch(apiUrl(base, path, c.teamId), { ...init, headers: headers(c) })
    if (!r.ok) throw new Error(`Vercel Sandbox ${errorOf(r)}`)
    return r
  }
  return {
    async create(o) {
      const r = await call('/v3/sandboxes', { method: 'POST', body: createBody(c, o) })
      const info = readSandbox(r.text)
      if (!info) throw new Error('Vercel Sandbox: unreadable create response')
      return info
    },
    async get(s) {
      const r = await call(`/v2/sandboxes/sessions/${encodeURIComponent(s.sessionId)}`, { method: 'GET' })
      const info = readSandbox(r.text, s.name)
      if (!info) throw new Error('Vercel Sandbox: unreadable session response')
      return { ...info, image: info.image ?? s.image }
    },
    async run(s, command, timeoutMs) {
      const r = await call(`/v2/sandboxes/sessions/${encodeURIComponent(s.sessionId)}/cmd`, {
        method: 'POST',
        body: commandBody(command, timeoutMs, s.cwd),
      })
      return readCommandStream(r.text)
    },
    async stop(s) {
      await call(`/v2/sandboxes/sessions/${encodeURIComponent(s.sessionId)}/stop`, { method: 'POST' })
    },
  }
}

